  cleanup = await useTemporaryDatabase();
});
afterAll(() => cleanup());

describe("scratch: bulkArchiveIssues", () => {
  it("enforces tenant scope, dedupes, skips, keeps archived rows, emits per archived id", async () => {
    const t = await createTenant("bulkscratch");
    const other = await createTenant("bulkother");
    const mk = (tenant: typeof t, title: string) =>
      issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title }));

    const a = await mk(t, "aaa");
    const b = await mk(t, "bbb");
    const c = await mk(t, "ccc");
    const foreign = await mk(other, "foreign");
    const pre = await issueService.archiveIssue(t.actors.member, t.org.id, c.id);
    const unknown = newId() as typeof a.id;

    // Tenant scope: input org differs from actor org.
    await expect(
      issueService.bulkArchiveIssues(t.actors.member, { orgId: other.org.id, issueIds: [a.id] }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const received: { issueId: string }[] = [];
    const off = subscribe("issue.archived", (p) => { received.push(p as { issueId: string }); });
    try {
      const result = await issueService.bulkArchiveIssues(t.actors.member, {
        orgId: t.org.id,
        issueIds: [b.id, a.id, b.id, c.id, foreign.id, unknown],
      });
      expect(result.archived).toEqual([b.id, a.id]);
      expect(result.skipped).toEqual([c.id, foreign.id, unknown]);
      expect(received.map((p) => p.issueId)).toEqual([b.id, a.id]);

      const cAfter = await issueRepo.findIssueById(t.org.id, c.id);
      expect(cAfter?.archivedAt).toBe(pre.archivedAt);
      const fAfter = await issueRepo.findIssueById(other.org.id, foreign.id);
      expect(fAfter?.archivedAt).toBeNull();
      const bAfter = await issueRepo.findIssueById(t.org.id, b.id);
      expect(bAfter?.archivedAt).not.toBeNull();
    } finally {
      off();
    }

    const empty = await issueService.bulkArchiveIssues(t.actors.member, { orgId: t.org.id, issueIds: [] });
    expect(empty).toEqual({ archived: [], skipped: [] });
  });

