    const t = await createTenant("bulkperm");
    const mine = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "mine" }));
    const assigned = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "assigned" }));
    await issueService.assignIssue(t.actors.member, { orgId: t.org.id, issueId: assigned.id, assigneeId: t.userIds.viewer });

    const received: unknown[] = [];
    const off = subscribe("issue.archived", (p) => { received.push(p); });
    try {
      // viewer may archive `assigned` by ownership, but not `mine`.
      await expect(
        issueService.bulkArchiveIssues(t.actors.viewer, { orgId: t.org.id, issueIds: [assigned.id, mine.id] }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
      expect(received).toHaveLength(0);
      expect((await issueRepo.findIssueById(t.org.id, assigned.id))?.archivedAt).toBeNull();
      expect((await issueRepo.findIssueById(t.org.id, mine.id))?.archivedAt).toBeNull();

      // Skipped ids are not permission-checked: archived `mine` for viewer is just skipped.
      const archivedMine = await issueService.archiveIssue(t.actors.member, t.org.id, mine.id);
      const skipOnly = await issueService.bulkArchiveIssues(t.actors.viewer, { orgId: t.org.id, issueIds: [mine.id] });
      expect(skipOnly).toEqual({ archived: [], skipped: [mine.id] });
      expect((await issueRepo.findIssueById(t.org.id, mine.id))?.archivedAt).toBe(archivedMine.archivedAt);

      // Ownership escalation applies per row: viewer archives its assigned issue.
      const ok = await issueService.bulkArchiveIssues(t.actors.viewer, { orgId: t.org.id, issueIds: [assigned.id] });
      expect(ok).toEqual({ archived: [assigned.id], skipped: [] });
      expect(received).toHaveLength(2);
    } finally {
      off();
    }
  });

  it("validates the schema bounds and id shape", () => {
    const org = "01HZZZOOOOOOOOOOOOOOOOOOOO";
    const id = newId();
    expect(bulkArchiveIssuesSchema.safeParse({ orgId: org, issueIds: [] }).success).toBe(false);
    expect(bulkArchiveIssuesSchema.safeParse({ orgId: org, issueIds: Array.from({ length: 51 }, () => id) }).success).toBe(false);
    expect(bulkArchiveIssuesSchema.safeParse({ orgId: org, issueIds: Array.from({ length: 50 }, () => id) }).success).toBe(true);
    expect(bulkArchiveIssuesSchema.safeParse({ orgId: org, issueIds: ["nope"] }).success).toBe(false);
  });
});

